                buf.readUnsignedShortLE(); // bearing to landmark
                buf.readUnsignedIntLE(); // distance to landmark

                position.setFixTime(new Date(buf.readUnsignedIntLE() * 1000));

                buf.readUnsignedByte(); // reserved
