                byte b2 = buf.readByte();
                switch (b2) {
                    case 0x01:
                        frame.writeByte('}');
                        break;
                    case 0x02:
                        frame.writeByte('[');
                        break;
                    case 0x03:
                        frame.writeByte(']');
                        break;
                    case 0x04:
                        frame.writeByte(',');
                        break;
                    case 0x05:
                        frame.writeByte('*');
                        break;
                    default:
                        throw new IllegalArgumentException(String.format(
                                "unexpected byte at %d: 0x%02x", buf.readerIndex() - 1, b2));
                }
                readerIndex += 2;
            } else {
                frame.writeByte(b1);
                readerIndex++;
            }
        }
        buf.readerIndex(endIndex);
        return frame;
    }

    return null;
}

@Override
protected Object decode(ChannelHandlerContext ctx, Channel channel, ByteBuf buf) throws Exception {
    List<Object> frames = new ArrayList<>();
    while (true) {
        int startIndex = buf.indexOf(buf.readerIndex(), buf.writerIndex(), '[');
        if (startIndex == -1) {
            break; // No more frames
        }
        int endIndex = buf.indexOf(startIndex, buf.writerIndex(), ']');
        if (endIndex == -1) {
            break; // Incomplete frame
        }
        ByteBuf frame = buf.slice(startIndex, endIndex - startIndex + 1);
        ByteBuf unescapedFrame = unescapeFrame(frame);
        frames.add(unescapedFrame);
        buf.readerIndex(endIndex + 1);
    }
    if (!frames.isEmpty()) {
        return frames;
    } else {
        return null;
    }
}

private ByteBuf unescapeFrame(ByteBuf frame) {
    ByteBuf output = Unpooled.buffer();
    for (int readerIndex = frame.readerIndex(); readerIndex < frame.writerIndex(); ) {
        byte b = frame.getByte(readerIndex);
        if (b == '}') {
            if (readerIndex + 1 >= frame.writerIndex()) {
                throw new IllegalArgumentException("Incomplete escape sequence at end of frame");
            }
            byte next = frame.getByte(readerIndex + 1);
            switch (next) {
                case 0x01:
                    output.writeByte('}');
                    break;
                case 0x02:
                    output.writeByte('[');
                    break;
                case 0x03:
                    output.writeByte(']');
                    break;
                case 0x04:
                    output.writeByte(',');
                    break;
                case 0x05:
                    output.writeByte('*');
                    break;
                default:
                    throw new IllegalArgumentException(String.format("unexpected byte at %d: 0x%02x", readerIndex + 1, next));
            }
            readerIndex += 2;
        } else {
            output.writeByte(b);
            readerIndex++;
        }
    }
    return output;
}

@Override
protected Object decode(ChannelHandlerContext ctx, Channel channel, ByteBuf buf) throws Exception {
    // Find the first '['
    int startIndex = buf.indexOf(buf.readerIndex(), buf.writerIndex(), (byte) '[');
    if (startIndex == -1) {
        return null; // No complete frame available
    }

    // Find the next ']' after the startIndex
    int endIndex = buf.indexOf(startIndex + 1, buf.writerIndex(), (byte) ']');
    if (endIndex == -1) {
        return null; // Incomplete frame
    }

    // Extract the bytes between '[' and ']', inclusive
    ByteBuf frame = buf.retainedSlice(startIndex, endIndex - startIndex + 1);

    // Process any escaped characters within the frame
    ByteBuf processedFrame = Unpooled.buffer();
    for (int i = 0; i < frame.readableBytes(); i++) {
        byte b = frame.getByte(i);
        if (b == '}') {
            if (i + 1 >= frame.readableBytes()) {
                throw new IllegalArgumentException("Incomplete escape sequence");
            }
            byte nextB = frame.getByte(i + 1);
            switch (nextB) {
                case 0x01:
                    processedFrame.writeByte('}');
                    break;
                case 0x02:
                    processedFrame.writeByte('[');
                    break;
                case 0x03:
                    processedFrame.writeByte(']');
                    break;
                case 0x04:
                    processedFrame.writeByte(',');
                    break;
                case 0x05:
                    processedFrame.writeByte('*');
                    break;
                default:
                    throw new IllegalArgumentException(String.format(
                            "unexpected byte at %d: 0x%02x", i + 1, nextB));
            }
            i++; // Skip the next byte as it's part of the escape sequence
        } else {
            processedFrame.writeByte(b);
        }
    }

    // Consume the frame from the buffer
    buf.readerIndex(endIndex + 1);

    return processedFrame;
}

