            groupValuesList.add(currentGroupValues);
            currentGroupValues = new HashMap<>(valuesByArg);
        }
    }

    // Add the last group's values
    groupValuesList.add(currentGroupValues);

    for (Map<DslArg, List<String>> groupValues : groupValuesList) {
